import{_ as t,c as a,o as r,ae as l}from"./chunks/framework.DI6M9D4h.js";const o="/assets/a17de550b718850611903ab1557a6545_MD5.88M3pqrf.jpg",i="/assets/lipo-battery-1.CoeZd_LF.jpg",s="/assets/battery-cable-1.CZ7z9hxE.jpeg",d="/assets/7fe8b8d50b93cdbc1e18bd6a916da055_MD5.DOH6tEzQ.jpg",n="/assets/7930331bc29015a2aca5d34da2173f5a_MD5.DQPmFPdy.jpg",h="/assets/1dc24afe34a286ddcd64902a283691a6_MD5.BNeYypVe.jpg",c="/assets/forager-default-keymap-1.DzGKRW10.svg",_=JSON.parse('{"title":"Forager Build Guide","description":"","frontmatter":{},"headers":[],"relativePath":"build-guides/forager/index.md","filePath":"build-guides/forager/index.md","lastUpdated":1760970437000}'),u={name:"build-guides/forager/index.md"};function p(f,e,g,b,m,y){return r(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="forager-build-guide" tabindex="-1">Forager Build Guide <a class="header-anchor" href="#forager-build-guide" aria-label="Permalink to &quot;Forager Build Guide&quot;">​</a></h1><p><a href="https://github.com/firstcontributions/first-contributions" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/PRs-welcome-brightgreen.svg?style=flat-square" alt="PRs Welcome" loading="lazy"></a><a href="https://discord.gg/frjFXZB" title="Redirect to Keycapsss Discord" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/548530462419582996?style=flat-square&amp;logo=discord&amp;logoColor=white" alt="Discord" loading="lazy"></a><a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/License-CC%20BY--NC--SA%204.0-lightgrey.svg?style=flat-square" alt="License: CC BY-NC-SA 4.0" loading="lazy"></a></p><h2 id="bom" tabindex="-1">BOM <a class="header-anchor" href="#bom" aria-label="Permalink to &quot;BOM&quot;">​</a></h2><h3 id="parts-included-in-the-kit" tabindex="-1">Parts included in the kit <a class="header-anchor" href="#parts-included-in-the-kit" aria-label="Permalink to &quot;Parts included in the kit&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Part name</th><th style="text-align:left;">Qty</th><th style="text-align:left;">Remarks</th></tr></thead><tbody><tr><td style="text-align:left;">Forager PCB (left, right side)</td><td style="text-align:left;">2</td><td style="text-align:left;">Fully assembled</td></tr><tr><td style="text-align:left;">Case</td><td style="text-align:left;">2</td><td style="text-align:left;">3D printed with black PLA</td></tr><tr><td style="text-align:left;">Tenting feet</td><td style="text-align:left;">4</td><td style="text-align:left;">3D printed with black PLA</td></tr><tr><td style="text-align:left;">Screws</td><td style="text-align:left;"></td><td style="text-align:left;">Black countersunk M2x4 screws (with spare screws)</td></tr><tr><td style="text-align:left;">Rubber feet</td><td style="text-align:left;"></td><td style="text-align:left;"></td></tr></tbody></table><h3 id="additionally-required-parts" tabindex="-1">Additionally required parts <a class="header-anchor" href="#additionally-required-parts" aria-label="Permalink to &quot;Additionally required parts&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Part name</th><th style="text-align:left;">Qty</th><th style="text-align:left;">Remarks</th></tr></thead><tbody><tr><td style="text-align:left;">Choc V1 switches</td><td style="text-align:left;">34</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">Choc V1 keycaps</td><td style="text-align:left;">34</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">LiPo 1S 3.7V battery</td><td style="text-align:left;">2</td><td style="text-align:left;">Optional with a JST ACH connector</td></tr><tr><td style="text-align:left;">Screwdriver</td><td style="text-align:left;"></td><td style="text-align:left;">Torx T6</td></tr></tbody></table><h2 id="battery" tabindex="-1">Battery <a class="header-anchor" href="#battery" aria-label="Permalink to &quot;Battery&quot;">​</a></h2><p>You need a Lipo 3.7V (1 cell) battery. The battery should have the max. dimensions to fit in the case. Width: 15mm Length: 34mm, Thickness: 3mm</p><p>The board has a JST ACH connector or if your battery does not have the right connector, your can solder the two cable direct on the PCB.</p><p><a href="img/a17de550b718850611903ab1557a6545_MD5.jpg"><img src="'+o+'" alt="401230 LiPo 1cell 3.7v battery" loading="lazy"></a><em>401230 Lipo with 120mAh and a JST ACH connector</em></p><p><img src="'+i+'" alt="Lipo battery soldered" loading="lazy"><em>Lipo battery without JST connector, with cables directly soldered to the PCB. <strong>Red = (+) , Black = (-)</strong></em></p><h3 id="where-to-buy" tabindex="-1">Where to buy <a class="header-anchor" href="#where-to-buy" aria-label="Permalink to &quot;Where to buy&quot;">​</a></h3><p>You can search for &quot;301230 lipo&quot; or &quot;401230 lipo&quot;. Below is a handpicked list of compatible batteries.</p><ul><li><a href="https://s.click.aliexpress.com/e/_EuJ4GwD" target="_blank" rel="noreferrer">Aliexpress (Int) - Lipo 120mAh with JST ACH connector *</a></li><li><a href="https://www.littlekeyboards.com/collections/miscellaneous/products/battery-w-jst-connector" target="_blank" rel="noreferrer">Little Keyboards (US)</a></li><li><a href="https://powercells.de/110mah-401230-lipo-3-7v-akku.html" target="_blank" rel="noreferrer">Powercells (DE) - JST-P connector must be removed</a></li><li><a href="https://amzn.to/3EdJCsy" target="_blank" rel="noreferrer">Amazon (DE) - 301230 110 mAh withou connector *</a></li></ul><h2 id="screws" tabindex="-1">Screws <a class="header-anchor" href="#screws" aria-label="Permalink to &quot;Screws&quot;">​</a></h2><p>Use a Torx T6 screwdriver and tighten the screws carefully to avoid damage. The set includes some spare screws.</p><h2 id="assembly" tabindex="-1">Assembly <a class="header-anchor" href="#assembly" aria-label="Permalink to &quot;Assembly&quot;">​</a></h2><ol><li><p>Check that you have all required parts</p><ul><li>[ ] Image with all parts</li></ul></li><li><p>Attach or solder the battery cable to the PCB and secure the battery with the double-sided adhesive tape. <a href="#battery">See above</a></p></li><li><p>Insert the PCB into the bottom of the case. Start with the USB connector and then push the overlying side down. Tighten the 5x screws. Ensure that the battery cable is not trapped between the case and the soldering nut. <img src="'+s+'" alt="Battery cable" loading="lazy"></p></li><li><p>Place the top plate on the on PCB. Take a choc v1 switch and check that the 2 metal pins are straight. <a href="img/7fe8b8d50b93cdbc1e18bd6a916da055_MD5.jpg"><img src="'+d+'" alt="Choc switch pin align" loading="lazy"></a></p><p>Check the orientation before inserting the switch. Insert the switch into one of the outer cut-outs. <a href="img/7930331bc29015a2aca5d34da2173f5a_MD5.jpg"><img src="'+n+'" alt="Forager top view" loading="lazy"></a></p></li><li><p>Repeat the last step for the remaining 3 outer switch cut-outs and then proceed with the remaining switch cut-outs. This will align the top plate in the correct position. <a href="img/1dc24afe34a286ddcd64902a283691a6_MD5.jpg"><img src="'+h+'" alt="Forager top view" loading="lazy"></a></p></li><li><p>Screw the 4x screws into the top plate.</p></li></ol><h2 id="typing-test" tabindex="-1">Typing Test <a class="header-anchor" href="#typing-test" aria-label="Permalink to &quot;Typing Test&quot;">​</a></h2><p>With Forager fully assembled, it&#39;s time to test it out! The <a href="https://config.qmk.fm/#/test" target="_blank" rel="noreferrer">QMK Configurator</a> pag gives you visual feedback.</p><h3 id="default-keymap" tabindex="-1">Default keymap <a class="header-anchor" href="#default-keymap" aria-label="Permalink to &quot;Default keymap&quot;">​</a></h3><p>The Forager ships with the following default keymap:</p><p><img src="'+c+'" alt="Forager default keymap" loading="lazy"></p><p><em>Keymap image created with <a href="https://github.com/caksoylar/keymap-drawer%20https://keymap-drawer.streamlit.app" target="_blank" rel="noreferrer">keymap-drawer.streamlit.app</a></em></p><h3 id="zmk-studio" tabindex="-1">ZMK Studio <a class="header-anchor" href="#zmk-studio" aria-label="Permalink to &quot;ZMK Studio&quot;">​</a></h3><p>With ZMK Studio you can change the keymap without flashing a new firmware. The pre flashed firmware has ZMK Studio enabled.</p><ol><li>Connect the centre half to your computer using a USB cable.</li><li>Open the <a href="https://zmk.studio" target="_blank" rel="noreferrer">ZMK Studio website</a>, or download the latest release of the <a href="https://github.com/zmkfirmware/zmk-studio/releases" target="_blank" rel="noreferrer">cross platform application</a>.</li><li>To unlock the keyboard, press the <kbd>studio_unlock</kbd> key <em>(first column, second row)</em> in the <code>adj</code> layer. To access the <code>adj</code> layer, hold the <kbd>sym</kbd> and the <kbd>num</kbd> key.</li><li>Now you can change the keymap to suit your needs. Not all ZMK features are supported by ZMK Studio. More information <a href="https://zmk.dev/docs/features/studio#capabilities" target="_blank" rel="noreferrer">here</a>.</li></ol><h2 id="wireless" tabindex="-1">Wireless <a class="header-anchor" href="#wireless" aria-label="Permalink to &quot;Wireless&quot;">​</a></h2><p>ZMK will automatically start advertising to allow new hosts to connect. From your computer, go to the bluetooth preferences and add a device. You should see a device named &quot;Forager&quot; in the list. Click that item to connect. Once connected over bluetooth, you should be able to start typing.</p><p>To use more than one host/device with you Forager, you&#39;ll need to use different profiles to manage the connection/communication with each device. To learn more, read up on ZMK&#39;s <a href="https://zmk.dev/docs/features/bluetooth" target="_blank" rel="noreferrer">bluetooth feature</a>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><h3 id="i-have-bluetooth-connection-issue" tabindex="-1">I have bluetooth connection issue <a class="header-anchor" href="#i-have-bluetooth-connection-issue" aria-label="Permalink to &quot;I have bluetooth connection issue&quot;">​</a></h3><p>Do a complete reset on both half&#39;s.</p><ol><li>Download the follwowing files: <ul><li><a href="/firmware/settings_reset-seeeduino_xiao_ble-zmk.uf2" download="">settings_reset-seeeduino_xiao_ble-zmk.uf2</a> (factory reset the XIAO BLE)</li><li><a href="/firmware/forager_left.rgbled_adapter-seeeduino_xiao_ble-zmk.uf2" download="">forager_left.rgbled_adapter-seeeduino_xiao_ble-zmk.uf2</a> (firmware for the left half)</li><li><a href="/firmware/forager_right.rgbled_adapter-seeeduino_xiao_ble-zmk.uf2" download="">forager_right.rgbled_adapter-seeeduino_xiao_ble-zmk.uf2</a> (firmware for the right half)</li></ul></li><li>Connect left half via usb to you computer</li><li>Double tap the reset button on the back twice</li><li>A mass storage device named XIAO BLE should appear on the host</li><li>Drag and drop <code>settings_reset-seeeduino_xiao_ble-zmk.uf2</code> file to the storage drive. The XIAO BLE will automatically reset. Wait 5 seconds.</li><li>Start from step 3, but not drag and drop the <code>forager_left.rgbled_adapter-seeeduino_xiao_ble-zmk.uf2</code> file.</li></ol><p>Do the speps above again for the right half and use the <code>forager_right.rgbled_adapter-seeeduino_xiao_ble-zmk.uf2</code> file.</p><p>[* affiliated links]</p>',37)])])}const w=t(u,[["render",p]]);export{_ as __pageData,w as default};
